export const HISTORICAL_KINGDOM_BY_CODE = Object.fromEntries(
  HISTORICAL_KINGDOMS.map((k) => [k.code, k])
);

export function getKingdomCentroid(code) {
  const poly = kingdomPolygons[code];
  if (!poly || poly.length === 0) return [0.5, 0.5];
  let sx = 0, sy = 0;
  for (let i = 0; i < poly.length; i++) {
    sx += poly[i][0];
    sy += poly[i][1];
  }
  return [sx / poly.length, sy / poly.length];
}

export function getKingdomLabelPosition(code, poly, currentYear = 1500) {
  const eraStart = getCanonicalEraStart(currentYear);
  const eraOverride = ERA_HISTORICAL_POLYGONS[eraStart]?.[code];
  const activePoly = eraOverride || poly || kingdomPolygons[code];

  if (!activePoly || activePoly.length < 3) {
    return kingdomLabelPositions[code] || [0.5, 0.5];
  }

  if (!eraOverride && kingdomLabelPositions[code]) {
    return kingdomLabelPositions[code];
  }

  let a = 0, cx = 0, cy = 0;
  for (let i = 0; i < activePoly.length; i++) {
    const [x1, y1] = activePoly[i];
    const [x2, y2] = activePoly[(i + 1) % activePoly.length];
    const factor = x1 * y2 - x2 * y1;
    a += factor;
    cx += (x1 + x2) * factor;
    cy += (y1 + y2) * factor;
  }
  a = a / 2;
  if (Math.abs(a) < 1e-7) {
    return kingdomLabelPositions[code] || [0.5, 0.5];
  }
  return [
    Math.round((cx / (6 * a)) * 10000) / 10000,
    Math.round((cy / (6 * a)) * 10000) / 10000
  ];
}

const _eraResolutionCache = new Map();

export function invalidateCartographyCache() {
  _eraResolutionCache.clear();
}

const _r4 = (v) => Math.round(v * 10000) / 10000;
const _key = (p) => `${_r4(p[0]).toFixed(4)},${_r4(p[1]).toFixed(4)}`;

function _edgeKey(a, b) {
  const ka = _key(a);
  const kb = _key(b);
  return ka < kb ? `${ka}|${kb}` : `${kb}|${ka}`;
}

function _hash(str) {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h >>> 0;
}

function _rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (Math.imul(a, 1664525) + 1013904223) >>> 0;
    return a / 4294967296;
  };
}

export function refinePolygon(code, basePoly, resolution, eraStart = 1500) {
  if (!basePoly || basePoly.length < 3) return basePoly;
  const profile = MAP_RESOLUTION_PROFILES[resolution];
  if (!profile) return basePoly;

  const refined = [];
  const n = basePoly.length;

  for (let i = 0; i < n; i++) {
    const a = basePoly[i];
    const b = basePoly[(i + 1) % n];
    refined.push(a);

    const ka = _key(a);
    const kb = _key(b);
    if (ka === kb) continue;

    const isForward = ka < kb;
    const u = isForward ? a : b;
    const v = isForward ? b : a;
    const ek = isForward ? `${ka}|${kb}` : `${kb}|${ka}`;
    const depth = profile.coastDepth;
    const rough = profile.landRough || profile.coastRough;
    const cap = profile.landCap || profile.coastCap;

    if (depth <= 0) continue;

    // Canonical undirected edge seed (independent of country code & traversal direction)
    // guarantees watertight, zero-overlap shared borders across all resolution tiers.
    const segSeed = _hash(ek);
    const rand = _rng(segSeed);

    function subdivide(p1, p2, d, scale) {
      if (d === 0) return [p1];
      const mx = (p1[0] + p2[0]) / 2;
      const my = (p1[1] + p2[1]) / 2;
      const dx = p2[0] - p1[0];
      const dy = p2[1] - p1[1];
      const len = Math.hypot(dx, dy);
      if (len < 0.0005) return [p1];

      const nx = -dy / len;
      const ny = dx / len;
      const mag = Math.min(len * scale, cap) * (rand() - 0.5) * 2;
      const mid = [
        Math.round((mx + nx * mag) * 10000) / 10000,
        Math.round((my + ny * mag) * 10000) / 10000
      ];

      const left = subdivide(p1, mid, d - 1, scale * profile.decay);
      const right = subdivide(mid, p2, d - 1, scale * profile.decay);
      return left.concat(right);
    }

    const subs = subdivide(u, v, depth, rough);
    const intermediates = subs.slice(1);
    if (!isForward) intermediates.reverse();
    for (let k = 0; k < intermediates.length; k++) {
      refined.push(intermediates[k]);
    }
  }

  return refined;
}

export function getCanonicalEraStart(simYear = 1500) {
  if (simYear >= 1989) return "1989";
  if (simYear >= 1920) return "1920";
  if (simYear >= 1860) return "1860";
  if (simYear >= 1750) return "1750";
  return "1500";
}

export function getKingdomPolygon(code, simYear = 1500, resolution = "fast", customBasePolygon = null) {
  const eraStart = getCanonicalEraStart(simYear);
  const eraOverride = ERA_HISTORICAL_POLYGONS[eraStart]?.[code];
  const basePoly = customBasePolygon || eraOverride || kingdomPolygons[code];
  if (!basePoly) return null;
  if (!resolution || resolution === "fast" || !MAP_RESOLUTION_PROFILES[resolution]) return basePoly;

  const sig = customBasePolygon ? _hash(JSON.stringify(customBasePolygon)) : 0;
  const cacheKey = `${code}:${eraStart}:${resolution}:${sig}`;
  let poly = _eraResolutionCache.get(cacheKey);
  if (!poly) {
    poly = refinePolygon(code, basePoly, resolution, eraStart);
    _eraResolutionCache.set(cacheKey, poly);
  }
  return poly;
}

function _ptInPoly(x, y, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const xi = poly[i][0], yi = poly[i][1];
    const xj = poly[j][0], yj = poly[j][1];
    if (((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi)) {
      inside = !inside;
    }
  }
  return inside;
}

function _bounds(p) {
  let minX = 1, maxX = 0, minY = 1, maxY = 0;
  for (const [x, y] of p) {
    if (x < minX) minX = x;
    if (x > maxX) maxX = x;
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;
  }
  return { minX, maxX, minY, maxY };
}

export function evaluateSpatialEmergence(candidateCode, candidatePoly, activeStatesWithPolys) {
  if (!candidatePoly || candidatePoly.length < 3) {
    return { status: "free_to_form", overlapRatio: 0, suzerainCode: null, claimable: true };
  }
  const bc = _bounds(candidatePoly);
  let totalCandidateSamples = 0;
  const overlapByOwner = {};

  for (let sx = 0; sx < 12; sx++) {
    for (let sy = 0; sy < 12; sy++) {
      const x = bc.minX + ((bc.maxX - bc.minX) * (sx + 0.5)) / 12;
      const y = bc.minY + ((bc.maxY - bc.minY) * (sy + 0.5)) / 12;
      if (!_ptInPoly(x, y, candidatePoly)) continue;
      totalCandidateSamples++;
      for (const state of activeStatesWithPolys) {
        if (state.code === candidateCode || !state.poly || state.poly.length < 3) continue;
        const bs = _bounds(state.poly);
        if (x < bs.minX || x > bs.maxX || y < bs.minY || y > bs.maxY) continue;
        if (_ptInPoly(x, y, state.poly)) {
          overlapByOwner[state.code] = (overlapByOwner[state.code] || 0) + 1;
        }
      }
    }
  }

  if (totalCandidateSamples === 0) {
    return { status: "free_to_form", overlapRatio: 0, suzerainCode: null, claimable: true };
  }

  let dominantOwner = null;
  let maxHits = 0;
  let totalHits = 0;
  for (const [ownerCode, hits] of Object.entries(overlapByOwner)) {
    totalHits += hits;
    if (hits > maxHits) {
      maxHits = hits;
      dominantOwner = ownerCode;
    }
  }

  const dominantRatio = maxHits / totalCandidateSamples;
  const totalOverlapRatio = Math.min(1, totalHits / totalCandidateSamples);

  if (dominantRatio >= 0.85) {
    return {
      status: "client_state",
      overlapRatio: dominantRatio,
      suzerainCode: dominantOwner,
      isClientState: true,
      claimable: false,
    };
  }
  if (totalOverlapRatio > 0.02) {
    return {
      status: "partial_carve",
      overlapRatio: totalOverlapRatio,
      suzerainCode: null,
      isClientState: false,
      claimable: true,
    };
  }
  return {
    status: "free_to_form",
    overlapRatio: 0,
    suzerainCode: null,
    isClientState: false,
    claimable: true,
  };
}
